'use client';

import { useState } from 'react';
import { useCall, useCallStateHooks } from '@stream-io/video-react-sdk';
import { Mic, MicOff, Video, VideoOff } from 'lucide-react';
import { Button } from './ui/button';

const HostControls = () => {
  const call = useCall();
  const { useParticipants } = useCallStateHooks();
  const participants = useParticipants();

  if (!call) return null;

  // Check if current user is the host (creator of the call)
  const isHost = call.state.createdBy?.id === call.currentUserId;

  if (!isHost) return null;

  const handleMuteParticipant = async (participantId: string) => {
    try {
      await call.microphone.disableForParticipant(participantId);
    } catch (error) {
      console.error('Failed to mute participant:', error);
    }
  };

  const handleUnmuteParticipant = async (participantId: string) => {
    try {
      await call.microphone.enableForParticipant(participantId);
    } catch (error) {
      console.error('Failed to unmute participant:', error);
    }
  };

  const handleDisableVideoParticipant = async (participantId: string) => {
    try {
      await call.camera.disableForParticipant(participantId);
    } catch (error) {
      console.error('Failed to disable video for participant:', error);
    }
  };

  const handleEnableVideoParticipant = async (participantId: string) => {
    try {
      await call.camera.enableForParticipant(participantId);
    } catch (error) {
      console.error('Failed to enable video for participant:', error);
    }
  };

  return (
    <div className="bg-dark-1 p-4 rounded-lg text-white max-h-96 overflow-y-auto">
      <h3 className="text-lg font-bold mb-4">Host Controls</h3>
      <div className="space-y-2">
        {participants
          .filter((p) => p.userId !== call.currentUserId)
          .map((participant) => (
            <div key={participant.sessionId} className="flex items-center justify-between bg-dark-2 p-2 rounded">
              <span className="text-sm">{participant.name || participant.userId}</span>
              <div className="flex gap-2">
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => handleMuteParticipant(participant.sessionId)}
                  className="p-1"
                >
                  <MicOff size={16} className="text-red-500" />
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => handleUnmuteParticipant(participant.sessionId)}
                  className="p-1"
                >
                  <Mic size={16} className="text-green-500" />
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => handleDisableVideoParticipant(participant.sessionId)}
                  className="p-1"
                >
                  <VideoOff size={16} className="text-red-500" />
                </Button>
